score = 85

if score >= 90:
    grade = 'Distinction'
elif score >= 70:
    grade = 'Passing'
else:
    grade = 'Needs Improvement'

print(f'Assessment score {score}% receives status: {grade}')

# Expected Output:
# Assessment score 85% receives status: Passing

